window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bc4385de43e86bf1"]={"versions": [{"id": "FIG-bc4385de43e86bf1", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, Paket- und FIBEX-Elementen sowie wechselseitigen Abhängigkeiten und Unter-Clustern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code>, die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Rekursive Assoziation <code>+subSoftwareCluster</code> [0..\\*] («atpSplitable») auf <code>SoftwareClusterDesign</code>.</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..\\*] («atpSplitable») auf <code>FibexElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..1] («atpUriDef») auf <code>MachineDesign</code> (erbt via <code>FibexElement</code> und <code>AtpStructureElement</code> von <code>PackageableElement</code>), welches das Attribut <code>+pnResetTimer : TimeValue [0..1]</code> deklariert.</li>\n<li>Assoziation <code>+requiredPackageElement</code> [0..\\*] («atpSplitable») auf <code>UploadablePackageElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Komposition <code>+dependsOn</code> [0..\\*] («atpSplitable») mit Rückrolle <code>+dependentSoftwareClusterDesign</code> [0..1] auf die Assoziationsklasse <code>SoftwareClusterDesignDependency</code> mit Attribut <code>+dependency : String «atpSplitable»</code>.</li>\n<li>Komposition <code>+diagnosticAddress</code> [0..\\*] («atpSplitable») auf die abstrakte Klasse <code>SoftwareClusterDiagnosticAddress</code> mit Attribut <code>+addressSemantics : SoftwareClusterDiagnosticAddressSemanticsEnum</code>. Spezialisiert wird diese durch <code>SoftwareClusterDoipDiagnosticAddress</code> mit Attribut <code>+diagnosticAddress : PositiveInteger [0..1]</code>.</li>\n<li>Enumeration <code>SoftwareClusterDiagnosticAddressSemanticsEnum</code> mit den Literalen <code>physicalAddress</code> und <code>functionalAddress</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}, {"id": "FIG-970fcdbe17a0d3e8", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, Paket- und FIBEX-Elementen sowie wechselseitigen Abhängigkeiten und Unter-Clustern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code>, die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Rekursive Assoziation <code>+subSoftwareCluster</code> [0..\\*] («atpSplitable») auf <code>SoftwareClusterDesign</code>.</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..\\*] («atpSplitable») auf <code>FibexElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..1] («atpUriDef») auf <code>MachineDesign</code> (erbt via <code>FibexElement</code> und <code>AtpStructureElement</code> von <code>PackageableElement</code>), welches die Attribute <code>+accessControl : AccessControlEnum [0..1]</code> und <code>+pnResetTimer : TimeValue [0..1]</code> deklariert.</li>\n<li>Assoziation <code>+requiredPackageElement</code> [0..\\*] («atpSplitable») auf <code>UploadablePackageElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Komposition <code>+dependsOn</code> [0..\\*] («atpSplitable») mit Rückrolle <code>+dependentSoftwareClusterDesign</code> [0..1] auf die Assoziationsklasse <code>SoftwareClusterDesignDependency</code> mit Attribut <code>+dependency : String</code>.</li>\n<li>Komposition <code>+diagnosticAddress</code> [0..\\*] («atpSplitable») auf die abstrakte Klasse <code>SoftwareClusterDiagnosticAddress</code> mit Attribut <code>+addressSemantics : SoftwareClusterDiagnosticAddressSemanticsEnum</code>. Spezialisiert wird diese durch <code>SoftwareClusterDoipDiagnosticAddress</code> mit Attribut <code>+diagnosticAddress : PositiveInteger [0..1]</code>.</li>\n<li>Enumeration <code>SoftwareClusterDiagnosticAddressSemanticsEnum</code> mit den Literalen <code>physicalAddress</code> und <code>functionalAddress</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}, {"id": "FIG-b2b9df030148e21a", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, Paket- und FIBEX-Elementen sowie wechselseitigen Abhängigkeiten und Unter-Clustern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code>, die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+containedProcess</code> [0..\\*] («atpSplitable») auf <code>ProcessDesign</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Rekursive Assoziation <code>+subSoftwareCluster</code> [0..\\*] («atpSplitable») auf <code>SoftwareClusterDesign</code>.</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..\\*] («atpSplitable») auf <code>FibexElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..1] («atpUriDef») auf <code>MachineDesign</code> (erbt via <code>FibexElement</code> und <code>AtpStructureElement</code> von <code>PackageableElement</code>), welches die Attribute <code>+accessControl : AccessControlEnum [0..1]</code> und <code>+pnResetTimer : TimeValue [0..1]</code> deklariert.</li>\n<li>Assoziation <code>+requiredPackageElement</code> [0..\\*] («atpSplitable») auf <code>UploadablePackageElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Komposition <code>+dependsOn</code> [0..\\*] («atpSplitable») mit Rückrolle <code>+dependentSoftwareClusterDesign</code> [0..1] auf die Assoziationsklasse <code>SoftwareClusterDesignDependency</code> mit Attribut <code>+dependency : String</code>.</li>\n<li>Komposition <code>+diagnosticAddress</code> [0..\\*] («atpSplitable») auf die abstrakte Klasse <code>SoftwareClusterDiagnosticAddress</code> mit Attribut <code>+addressSemantics : SoftwareClusterDiagnosticAddressSemanticsEnum</code>. Spezialisiert wird diese durch <code>SoftwareClusterDoipDiagnosticAddress</code> mit Attribut <code>+diagnosticAddress : PositiveInteger [0..1]</code>.</li>\n<li>Enumeration <code>SoftwareClusterDiagnosticAddressSemanticsEnum</code> mit den Literalen <code>physicalAddress</code> und <code>functionalAddress</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}, {"id": "FIG-0aafea1f9bfc82b9", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, Paket- und FIBEX-Elementen sowie wechselseitigen Abhängigkeiten und Unter-Clustern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code>, die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt und zusätzlich <code>SoftwareActivationDependency</code> (mit Stereotyp <code>«atpClassifier»</code>) spezialisiert.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+containedProcess</code> [0..\\*] («atpSplitable») auf <code>ProcessDesign</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Rekursive Assoziation <code>+subSoftwareCluster</code> («atpSplitable») auf <code>SoftwareClusterDesign</code>.</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..\\*] («atpSplitable») auf <code>FibexElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..1] («atpUriDef») auf <code>MachineDesign</code> (erbt via <code>FibexElement</code> und <code>AtpStructureElement</code> von <code>PackageableElement</code>), welches die Attribute <code>+accessControl : AccessControlEnum [0..1]</code> und <code>+pnResetTimer : TimeValue [0..1]</code> deklariert.</li>\n<li>Assoziation <code>+requiredPackageElement</code> [0..\\*] («atpSplitable») auf <code>UploadablePackageElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Komposition <code>+dependsOn</code> [0..\\*] («atpSplitable») mit Rückrolle <code>+dependentSoftwareClusterDesign</code> [0..1] auf die Assoziationsklasse <code>SoftwareClusterDesignDependency</code> mit Attribut <code>+dependency : String</code>.</li>\n<li>Komposition <code>+diagnosticAddress</code> [0..\\*] («atpSplitable») auf die abstrakte Klasse <code>SoftwareClusterDiagnosticAddress</code> mit Attribut <code>+addressSemantics : SoftwareClusterDiagnosticAddressSemanticsEnum</code>. Spezialisiert wird diese durch <code>SoftwareClusterDoipDiagnosticAddress</code> mit Attribut <code>+diagnosticAddress : PositiveInteger [0..1]</code>.</li>\n<li>Enumeration <code>SoftwareClusterDiagnosticAddressSemanticsEnum</code> mit den Literalen <code>physicalAddress</code> und <code>functionalAddress</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}, {"id": "FIG-798932b41c6f27dc", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, Paket- und FIBEX-Elementen sowie wechselseitigen Abhängigkeiten und Unter-Clustern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code> (mit Stereotyp <code>«atpClassifier»</code>), die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+containedProcess</code> [0..\\*] («atpSplitable») auf <code>ProcessDesign</code> (erbt von <code>ARElement</code>).</li>\n<li>Rekursive Assoziation <code>+dependsOn</code> [0..\\*] auf <code>SoftwareClusterDesign</code>.</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Rekursive Assoziation <code>+subSoftwareCluster</code> [0..\\*] («atpSplitable») auf <code>SoftwareClusterDesign</code>.</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..\\*] («atpSplitable») auf <code>FibexElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..1] («atpUriDef») auf <code>MachineDesign</code> (erbt via <code>FibexElement</code> und <code>AtpStructureElement</code> von <code>PackageableElement</code>), welches die Attribute <code>+accessControl : AccessControlEnum [0..1]</code>, <code>+pncPrepareSleepTimer : TimeValue [0..1]</code> und <code>+pnResetTimer : TimeValue [0..1]</code> deklariert.</li>\n<li>Assoziation <code>+requiredPackageElement</code> [0..\\*] («atpSplitable») auf <code>UploadablePackageElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Komposition <code>+diagnosticAddress</code> [0..\\*] («atpSplitable») auf die abstrakte Klasse <code>SoftwareClusterDiagnosticAddress</code> mit Attribut <code>+addressSemantics : SoftwareClusterDiagnosticAddressSemanticsEnum</code>. Spezialisiert wird diese durch <code>SoftwareClusterDoipDiagnosticAddress</code> mit Attribut <code>+diagnosticAddress : PositiveInteger [0..1]</code>.</li>\n<li>Enumeration <code>SoftwareClusterDiagnosticAddressSemanticsEnum</code> mit den Literalen <code>physicalAddress</code> und <code>functionalAddress</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}, {"id": "FIG-4077adf6ab178f65", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, Paket- und FIBEX-Elementen sowie wechselseitigen Abhängigkeiten und Unter-Clustern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code> (mit Stereotyp <code>«atpClassifier»</code>), die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+containedProcess</code> [0..\\*] («atpSplitable») auf <code>ProcessDesign</code> (erbt von <code>ARElement</code>).</li>\n<li>Rekursive Assoziation <code>+dependsOn</code> [0..\\*] auf <code>SoftwareClusterDesign</code>.</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Rekursive Assoziation <code>+subSoftwareCluster</code> [0..\\*] («atpSplitable») auf <code>SoftwareClusterDesign</code>.</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..\\*] («atpSplitable») auf <code>FibexElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..1] («atpUriDef») auf <code>MachineDesign</code> (erbt via <code>FibexElement</code> und <code>AtpStructureElement</code> von <code>PackageableElement</code>), welches die Attribute <code>+accessControl : AccessControlEnum [0..1]</code>, <code>+pncPrepareSleepTimer : TimeValue [0..1]</code> und <code>+pnResetTimer : TimeValue [0..1]</code> deklariert.</li>\n<li>Assoziation <code>+requiredPackageElement</code> [0..\\*] («atpSplitable») auf <code>UploadablePackageElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Komposition <code>+diagnosticAddress</code> [0..\\*] («atpSplitable») auf die abstrakte Klasse <code>SoftwareClusterDiagnosticAddress</code> mit Attribut <code>+addressSemantics : SoftwareClusterDiagnosticAddressSemanticsEnum</code>. Spezialisiert wird diese durch <code>SoftwareClusterDoipDiagnosticAddress</code> mit Attribut <code>+diagnosticAddress : PositiveInteger [0..1]</code>.</li>\n<li>Enumeration <code>SoftwareClusterDiagnosticAddressSemanticsEnum</code> mit den Literalen <code>physicalAddress</code> und <code>functionalAddress</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}, {"id": "FIG-56bdb6fcdc1ef92e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, Paket- und FIBEX-Elementen sowie wechselseitigen Abhängigkeiten und Unter-Clustern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code> (mit Stereotyp <code>«atpClassifier»</code>), die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+containedProcess</code> [0..\\*] («atpSplitable») auf <code>ProcessDesign</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..\\*] («atpSplitable») auf <code>FibexElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..\\*] («atpUriDef») auf <code>MachineDesign</code> (erbt via <code>FibexElement</code> und <code>AtpStructureElement</code> von <code>PackageableElement</code>), welches die Attribute <code>+accessControl : AccessControlEnum [0..1]</code>, <code>+pncPrepareSleepTimer : TimeValue [0..1]</code> und <code>+pnResetTimer : TimeValue [0..1]</code> deklariert.</li>\n<li>Assoziation <code>+requiredPackageElement</code> [0..\\*] («atpSplitable») auf <code>UploadablePackageElement</code> (erbt von <code>PackageableElement</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}, {"id": "FIG-201c29cd05c56142", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, Paket- und FIBEX-Elementen sowie wechselseitigen Abhängigkeiten und Unter-Clustern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code> (mit Stereotyp <code>«atpClassifier»</code>), die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+containedProcess</code> [0..\\*] («atpSplitable») auf <code>ProcessDesign</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..\\*] («atpSplitable») auf <code>FibexElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..\\*] («atpUriDef») auf <code>MachineDesign</code> (erbt via <code>FibexElement</code> von <code>PackageableElement</code> sowie von <code>UploadableDesignElement</code>). <code>MachineDesign</code> trägt das Stereotyp <code>«AtpStructureElement»</code> und deklariert die Attribute <code>+accessControl : AccessControlEnum [0..1]</code>, <code>+pncPrepareSleepTimer : TimeValue [0..1]</code> und <code>+pnResetTimer : TimeValue [0..1]</code>.</li>\n<li>Assoziation <code>+requiredDesignElement</code> [0..\\*] («atpSplitable») auf <code>UploadableDesignElement</code> (erbt von <code>UploadablePackageElement</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}, {"id": "FIG-ace819b3b93b836d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, FIBEX- und Design-Elementen, logischen DoIP-Adressen sowie Prozessen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code> (mit Stereotyp <code>«atpClassifier»</code>), die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+containedProcess</code> [0..\\*] («atpSplitable») auf <code>ProcessDesign</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..\\*] («atpSplitable») auf <code>FibexElement</code> (erbt von <code>PackageableElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..\\*] («atpUriDef») auf <code>MachineDesign</code> (erbt via <code>FibexElement</code> von <code>PackageableElement</code> sowie von <code>UploadableDesignElement</code>). <code>MachineDesign</code> trägt das Stereotyp <code>«AtpStructureElement»</code> und deklariert die Attribute <code>+accessControl : AccessControlEnum [0..1]</code>, <code>+pncPrepareSleepTimer : TimeValue [0..1]</code> und <code>+pnResetTimer : TimeValue [0..1]</code>.</li>\n<li>Assoziation <code>+requiredDesignElement</code> [0..\\*] («atpSplitable») auf <code>UploadableDesignElement</code> (erbt von <code>UploadablePackageElement</code>).</li>\n<li>Assoziation <code>+doIpLogicalAddress</code> [0..1] («atpSplitable») auf <code>DoIpLogicalAddress</code> (Stereotyp <code>«Identifiable»</code>), welches das Attribut <code>+logicalAddress : PositiveInteger [0..1]</code> deklariert.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich dargestellt ist <code>DoIpFunctionalClusterDesign</code> (erbt von <code>AbstractFunctionalClusterDesign</code>), welches per Komposition <code>+doIpLogicalAddress</code> [0..1] auf <code>DoIpLogicalAddress</code> referenziert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}, {"id": "FIG-a500be53df61a02a", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells für das Design von Software-Clustern (<code>SoftwareClusterDesign</code>) im Kontext der AUTOSAR Adaptive Platform (Manifest Specification). Das Modell beschreibt die strukturellen Entwurfsbeziehungen eines Software-Clusters zu Zielmaschinen, Diagnosebeiträgen, FIBEX- und Design-Elementen, logischen DoIP-Adressen sowie Prozessen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist <code>SoftwareClusterDesign</code> (mit Stereotyp <code>«atpClassifier»</code>), die von <code>ARElement</code> (welches <code>PackageableElement</code> ist) erbt.</p>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> deklariert die Attribute:</p>\n<ul class=\"fig-list\">\n<li><code>+installationBehavior : SoftwareClusterInstallationBehaviorEnum [0..1]</code></li>\n<li><code>+version : StrongRevisionLabelString [0..1]</code></li>\n</ul>\n<p class=\"fig-p\"><code>SoftwareClusterDesign</code> besitzt folgende Relationen:</p>\n<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredARElement</code> [0..\\*] («atpSplitable») auf <code>ARElement</code>.</li>\n<li>Assoziation <code>+containedProcess</code> [0..\\*] («atpSplitable») auf <code>ProcessDesign</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+diagnosticContribution</code> [0..\\*] («atpSplitable») auf <code>DiagnosticContributionSet</code> (erbt von <code>ARElement</code>).</li>\n<li>Assoziation <code>+intendedTargetMachine</code> [0..\\*] («atpUriDef») auf <code>MachineDesign</code> (erbt von <code>UploadableDesignElement</code>). <code>MachineDesign</code> trägt die Stereotypen <code>«AtpStructureElement»</code> und <code>«FibexElement»</code> und deklariert die Attribute <code>+accessControl : AccessControlEnum [0..1]</code>, <code>+pncPrepareSleepTimer : TimeValue [0..1]</code> und <code>+pnResetTimer : TimeValue [0..1]</code>.</li>\n<li>Assoziation <code>+requiredDesignElement</code> [0..\\*] («atpSplitable») auf <code>UploadableDesignElement</code> (erbt von <code>UploadablePackageElement</code>).</li>\n<li>Assoziation <code>+doIpLogicalAddress</code> [0..1] («atpSplitable») auf <code>DoIpLogicalAddress</code> (Stereotyp <code>«Identifiable»</code>), welches das Attribut <code>+logicalAddress : PositiveInteger [0..1]</code> deklariert.</li>\n</ul>\n<p class=\"fig-p\">Zusätzlich dargestellt ist <code>DoIpFunctionalClusterDesign</code> (erbt von <code>AbstractFunctionalClusterDesign</code>), welches per Komposition <code>+doIpLogicalAddress</code> [0..1] auf <code>DoIpLogicalAddress</code> referenziert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltensmodelle. Das Diagramm spezifiziert deklarative Modellstrukturen, Referenzbeziehungen und Multiplizitäten zur Konfigurations- und Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert normative AUTOSAR-M2-Metamodell-Elemente für die Software-Cluster-Modellierung. Stereotype wie <code>«atpSplitable»</code> kennzeichnen Eigenschaften, die über mehrere ARXML-Dateien aufgeteilt werden dürfen; <code>«atpUriDef»</code> steuert die referenzielle Adressierung von Zielmaschinen. Attributoptionalitäten ([0..1]) und Assoziationsmultiplizitäten ([0..\\*]) bestimmen die Validierungsregeln für AUTOSAR-Manifest-Modelle.</p>"}], "trans": [{"from": "FIG-bc4385de43e86bf1", "to": "FIG-970fcdbe17a0d3e8", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>accessControl: AccessControlEnum [0..1]</code> in Klasse <code>MachineDesign</code> hinzugefügt.</li>\n<li>Stereotyp <code>«atpSplitable»</code> am Attribut <code>dependency: String</code> von <code>SoftwareClusterDesignDependency</code> entfernt.</li>\n</ul>"}, {"from": "FIG-970fcdbe17a0d3e8", "to": "FIG-b2b9df030148e21a", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>ProcessDesign</code> (spezialisiert <code>ARElement</code>) neu hinzugefügt.</li>\n<li>Assoziation <code>+containedProcess 0..*</code> mit Stereotyp <code>«atpSplitable»</code> von <code>SoftwareClusterDesign</code> auf <code>ProcessDesign</code> neu hinzugefügt.</li>\n</ul>"}, {"from": "FIG-b2b9df030148e21a", "to": "FIG-0aafea1f9bfc82b9", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>SoftwareClusterDesign</code> spezialisiert zusätzlich <code>SoftwareActivationDependency</code> (mit Stereotyp <code>«atpClassifier»</code>).</li>\n<li>Multiplizität <code>0..*</code> an der Rolle <code>+subSoftwareCluster</code> entfernt (im Diagramm nun als <code>+subSoftwareCluster</code> ohne Kardinalitätsangabe dargestellt).</li>\n</ul>"}, {"from": "FIG-0aafea1f9bfc82b9", "to": "FIG-798932b41c6f27dc", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziationsklasse <code>SoftwareClusterDesignDependency</code> mitsamt Attribut <code>dependency: String</code> und Rollen <code>+dependsOn 0..*</code> bzw. <code>+dependentSoftwareClusterDesign 0..1</code> entfernt.</li>\n<li>Direkte Selbstassoziation <code>+dependsOn 0..*</code> an <code>SoftwareClusterDesign</code> eingefügt.</li>\n<li>Vererbung <code>SoftwareActivationDependency</code> an <code>SoftwareClusterDesign</code> entfernt (nur <code>«atpClassifier»</code> verbleibt).</li>\n<li>Attribut <code>pncPrepareSleepTimer: TimeValue [0..1]</code> in Klasse <code>MachineDesign</code> ergänzt.</li>\n<li>Multiplizität <code>0..<em></code> an der Rolle <code>+subSoftwareCluster</code> wieder explizit hinzugefügt (<code>+subSoftwareCluster 0..</em></code>).</li>\n</ul>"}, {"from": "FIG-798932b41c6f27dc", "to": "FIG-4077adf6ab178f65", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4077adf6ab178f65", "to": "FIG-56bdb6fcdc1ef92e", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>SoftwareClusterDiagnosticAddress</code> und Unterklasse <code>SoftwareClusterDoipDiagnosticAddress</code> entfernt.</li>\n<li>Enumeration <code>SoftwareClusterDiagnosticAddressSemanticsEnum</code> entfernt.</li>\n<li>Komposition <code>+diagnosticAddress 0..*</code> («atpSplitable») von <code>SoftwareClusterDesign</code> auf <code>SoftwareClusterDiagnosticAddress</code> entfernt.</li>\n<li>Selbstassoziationen <code>+dependsOn 0..<em></code> und <code>+subSoftwareCluster 0..</em></code> («atpSplitable») an <code>SoftwareClusterDesign</code> entfernt.</li>\n<li>Multiplizität der Assoziation <code>+intendedTargetMachine</code> von <code>0..1</code> auf <code>0..*</code> geändert.</li>\n</ul>"}, {"from": "FIG-56bdb6fcdc1ef92e", "to": "FIG-201c29cd05c56142", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziation <code>+requiredPackageElement</code> zu <code>UploadablePackageElement</code> ersetzt durch <code>+requiredDesignElement</code> [0..*] («atpSplitable») zu <code>UploadableDesignElement</code>.</li>\n<li>Klasse <code>UploadableDesignElement</code> (erbt von <code>UploadablePackageElement</code>) eingefügt; <code>MachineDesign</code> erbt nun von <code>UploadableDesignElement</code>.</li>\n<li>Layout des Klassendiagramms neu arrangiert (u. a. <code>ProcessDesign</code> und <code>DiagnosticContributionSet</code> links statt rechts angeordnet).</li>\n</ul>"}, {"from": "FIG-201c29cd05c56142", "to": "FIG-ace819b3b93b836d", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziation <code>+doIpLogicalAddress</code> [0..1] («atpSplitable») von <code>SoftwareClusterDesign</code> auf <code>DoIpLogicalAddress</code> ergänzt.</li>\n<li>Klasse <code>DoIpLogicalAddress</code> (Stereotyp <code>«Identifiable»</code>, Attribut <code>+logicalAddress : PositiveInteger [0..1]</code>) hinzugefügt.</li>\n<li>Klasse <code>DoIpFunctionalClusterDesign</code> (erbt von <code>AbstractFunctionalClusterDesign</code>) mit Komposition <code>+doIpLogicalAddress</code> [0..1] auf <code>DoIpLogicalAddress</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-ace819b3b93b836d", "to": "FIG-a500be53df61a02a", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Attribute <code>+installationBehavior : SoftwareClusterInstallationBehaviorEnum [0..1]</code> und <code>+version : StrongRevisionLabelString [0..1]</code> in <code>SoftwareClusterDesign</code> ergänzt.</li>\n<li>Assoziation <code>+requiredFibexElement</code> [0..*] entfällt.</li>\n<li>Klasse <code>FibexElement</code> entfällt als eigenständige Zwischenklasse im Diagramm; <code>MachineDesign</code> trägt nun direkt die Stereotypen/Basistypen <code>AtpStructureElement</code> und <code>FibexElement</code>.</li>\n<li>Assoziationspfeil <code>+intendedTargetMachine</code> nun von der Unterkante von <code>SoftwareClusterDesign</code> nach unten auf <code>MachineDesign</code> geführt.</li>\n</ul>"}]};
